def choose_move(observation):
    def sign(a, b):
        return 0 if a == b else (1 if a > b else -1)

    def clamp_dir(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def pos_list(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    def get_pos(keys):
        for k in keys:
            p = pos_list(observation.get(k))
            if p is not None:
                return p
        return [0, 0]

    def best_by_manhattan(points, sx, sy, prefer_far=False):
        best = None
        best_score = None
        for item in points or []:
            p = pos_list(item)
            if p is None:
                continue
            d = abs(p[0] - sx) + abs(p[1] - sy)
            score = (-d if prefer_far else d, p[0], p[1])
            if best is None or score < best_score:
                best = p
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = get_pos(["self_position"])
    ox, oy = get_pos(["opponent_position"])

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            dx = sign(ox, sx)
            dy = sign(oy, sy)
            return [clamp_dir(dx), clamp_dir(dy)]
        corners = [
            [0, 0],
            [0, observation.get("grid_height", 1) - 1],
            [observation.get("grid_width", 1) - 1, 0],
            [observation.get("grid_width", 1) - 1, observation.get("grid_height", 1) - 1],
        ]
        target = best_by_manhattan(corners, ox, oy, prefer_far=True) or [sx, sy]
        return [clamp_dir(sign(target[0], sx)), clamp_dir(sign(target[1], sy))]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        target = best_by_manhattan(targets, sx, sy)
        if target is None:
            if ox != sx or oy != sy:
                return [clamp_dir(sign(sx, ox)), clamp_dir(sign(sy, oy))]
            return [0, 0]
        return [clamp_dir(sign(target[0], sx)), clamp_dir(sign(target[1], sy))]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    target = best_by_manhattan(resources, sx, sy)
    if target is None:
        if ox != sx or oy != sy:
            return [clamp_dir(sign(ox, sx)), clamp_dir(sign(oy, sy))]
        return [0, 0]

    dx = clamp_dir(sign(target[0], sx))
    dy = clamp_dir(sign(target[1], sy))

    if ox != sx or oy != sy:
        if abs(target[0] - sx) + abs(target[1] - sy) == abs(ox - sx) + abs(oy - sy):
            away_dx = clamp_dir(sign(sx, ox))
            away_dy = clamp_dir(sign(sy, oy))
            if abs(target[0] - (sx + away_dx)) + abs(target[1] - (sy + away_dy)) < abs(target[0] - (sx + dx)) + abs(target[1] - (sy + dy)):
                dx, dy = away_dx, away_dy

    return [dx, dy]

